-
-	totallen = rctx->cryptlen + rctx->assoclen;
-
-	sg = qce_aead_prepare_dst_buf(req);
-	if (IS_ERR(sg))
-		return PTR_ERR(sg);
-	if (diff_dst) {
-		rctx->src_nents = sg_nents_for_len(req->src, totallen);
-		if (rctx->src_nents < 0) {
-			dev_err(qce->dev, "Invalid numbers of src SG.\n");
-			return -EINVAL;
-		}
-		rctx->src_sg = req->src;
