-	if (IS_CCM(flags)) {
-		if (authsize < 4 || authsize > 16 || authsize % 2)
-			return -EINVAL;
-		if (IS_CCM_RFC4309(flags) && (authsize < 8 || authsize % 4))
-			return -EINVAL;
