-	if (IS_ERR(ctx->fallback))
-		return PTR_ERR(ctx->fallback);
-
-	crypto_aead_set_reqsize_dma(tfm, sizeof(struct qce_aead_reqctx) +
-					 crypto_aead_reqsize(ctx->fallback));
