+++ b/drivers/media/radio/si470x/radio-si470x-usb.c
@@ -655,7 +655,7 @@ static int si470x_usb_driver_probe(struct usb_interface *intf,
 	if (radio->hdl.error) {
 		retval = radio->hdl.error;
 		dev_err(&intf->dev, "couldn't register control\n");
-		goto err_dev;
